#include "byte_bpe.hpp"
#include <cstdio>
int main(){try{using tao::text::ByteBpe;ByteBpe a,b;std::vector<std::string>train{"banana banana","banana bandana","<EOS> is literal","ab","cd"};a.fit(train,16);b.fit(train,16);if(a.merges!=b.merges)throw std::runtime_error("determinism");std::string all;for(int i=0;i<256;++i)all.push_back(char(i));for(auto s:{all,std::string("banana"),std::string("<EOS>"),std::string(""),std::string("unseen xyz")}){auto ids=a.encode(s);if(a.decode(ids)!=s)throw std::runtime_error("roundtrip");for(auto id:ids)if(id>=256&&id<261)throw std::runtime_error("special injection");}ByteBpe boundary;boundary.fit({"ab","cd"},8);if(boundary.merges.size()!=2)throw std::runtime_error("cross boundary");ByteBpe bad;bad.merges={{256,97}};bool rejected=false;try{bad.validate();}catch(const std::runtime_error&){rejected=true;}if(!rejected)throw std::runtime_error("invalid merge");printf("PASS deterministic fit, all-byte roundtrip, special isolation, message boundaries; merges=%zu\n",a.merges.size());return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
